// Sales Studio process overlay — the ONE seam where a client's assigned process
// version influences workflow execution.
//
// CRITICAL ARCHITECTURE RULE: the Workflow engine stays the only executor. This
// module never transitions a client. It produces a CONFIG-OVERLAID COPY of a
// workflow (safe values only: timing / message / assignment / branch-enabled /
// max-attempts) that the SAME engine then runs. Keys are the LIVE workflow's
// branch.id / action.id, generated by the simple editor off the same workflow,
// so an overlay can never reference a branch/action that doesn't exist.
//
// A client with NO active assignment → resolveProcessOverlay returns null → the
// engine runs the workflow's built-in hardcoded behavior unchanged (legacy path).

import type {
  Workflow,
  WorkflowBranch,
  WorkflowAction,
  FieldMapping,
  AppRecord,
  SalesWorkflowOverlay,
  SalesProcessVersion,
  ClientSalesProcessAssignment,
  SalesAssignmentStrategy,
} from '@/types';

/** Run-time context the overlay needs to make attempt-aware decisions. */
export interface SalesOverlayContext {
  /** The trigger follow-up's attempt number (data.followup_number), if any. */
  attemptNumber?: number | null;
  /** The rep on the trigger record, for the same_sales_rep strategy. */
  triggerRepFieldId?: string;
}

/** The field slug that holds the assignee/rep on a created follow-up. */
const REP_FIELD_SLUG = 'sales_rep';

/** True when an overlay actually changes anything (cheap short-circuit). */
function overlayIsEmpty(o: SalesWorkflowOverlay | undefined): boolean {
  if (!o) return true;
  return (
    !o.branches &&
    !o.timings &&
    !o.messages &&
    !o.assignments &&
    !o.max_attempts
  );
}

function applyAssignmentToMapping(
  mapping: FieldMapping,
  strategy: SalesAssignmentStrategy,
  fixedUserId: string | null | undefined,
): FieldMapping {
  switch (strategy) {
    case 'same_sales_rep':
      // Copy the rep from the trigger follow-up.
      return { ...mapping, source_type: 'trigger_field', trigger_field_id: REP_FIELD_SLUG };
    case 'current_user':
      return { ...mapping, source_type: 'current_user' };
    case 'fixed_user':
      return { ...mapping, source_type: 'static', static_value: fixedUserId ?? null };
    case 'role_least_workload':
      // Keep the role binding the workflow already has (overlay can't invent a
      // role); just force the least-workload selection strategy. If the mapping
      // has no role, this is a no-op fallback to its original source.
      if (mapping.role_id) {
        return { ...mapping, source_type: 'role_variable', selection_strategy: 'least_workload' };
      }
      return mapping;
    default:
      return mapping;
  }
}

function applyOverlayToActions(
  actions: WorkflowAction[],
  overlay: SalesWorkflowOverlay,
  ctx: SalesOverlayContext,
): WorkflowAction[] {
  const out: WorkflowAction[] = [];
  for (const action of actions) {
    // ── max_attempts: drop a retry create_record once the cap is hit ────────
    const cap = overlay.max_attempts?.[action.id];
    if (
      typeof cap === 'number' &&
      action.type === 'create_record' &&
      typeof ctx.attemptNumber === 'number' &&
      ctx.attemptNumber >= cap
    ) {
      // The next retry would exceed the configured cap — skip creating it.
      continue;
    }

    if (action.type === 'create_record') {
      const timing = overlay.timings?.[action.id];
      const assignment = overlay.assignments?.[action.id];
      if (!timing && !assignment) {
        out.push(action);
        continue;
      }
      const field_mappings = action.field_mappings.map((m) => {
        let next = m;
        if (timing && m.source_type === 'date_expression') {
          next = { ...next, date_expression: timing };
        }
        if (assignment && m.target_field_id === REP_FIELD_SLUG) {
          next = applyAssignmentToMapping(next, assignment.strategy, assignment.fixed_user_id);
        }
        return next;
      });
      out.push({ ...action, field_mappings });
      continue;
    }

    if (action.type === 'send_whatsapp_message') {
      const msg = overlay.messages?.[action.id];
      // Bilingual templates collapse to a single body; the engine has one body
      // slot (tokens resolved server-side). Prefer the active-language text,
      // falling back to whichever is present, else leave untouched.
      const replacement = msg?.ar?.trim() || msg?.en?.trim();
      if (replacement) {
        out.push({ ...action, body_template: replacement });
        continue;
      }
    }

    out.push(action);
  }
  return out;
}

function applyOverlayToBranch(
  branch: WorkflowBranch,
  overlay: SalesWorkflowOverlay,
  ctx: SalesOverlayContext,
): WorkflowBranch {
  return {
    ...branch,
    actions: applyOverlayToActions(branch.actions, overlay, ctx),
  };
}

/**
 * Return a CONFIG-OVERLAID copy of `workflow` for the engine to run, or the
 * same reference when the overlay is empty. Disabled branches are removed;
 * timing / message / assignment / max-attempts are rewritten in place.
 *
 * Pure + side-effect free — safe to unit test.
 */
export function applyProcessOverlayToWorkflow(
  workflow: Workflow,
  overlay: SalesWorkflowOverlay | undefined,
  ctx: SalesOverlayContext = {},
): Workflow {
  if (overlayIsEmpty(overlay) || !overlay) return workflow;

  // Branched shape.
  if (workflow.branches && workflow.branches.length > 0) {
    const branches = workflow.branches
      .filter((b) => overlay.branches?.[b.id]?.enabled !== false) // drop disabled
      .map((b) => {
        const bo = overlay.branches?.[b.id];
        const withLabels: WorkflowBranch =
          bo?.label_ar != null || bo?.label_en != null
            ? { ...b, label_ar: bo.label_ar ?? b.label_ar, label_en: bo.label_en ?? b.label_en }
            : b;
        return applyOverlayToBranch(withLabels, overlay, ctx);
      });
    return { ...workflow, branches };
  }

  // Legacy flat shape (conditions + actions, no branches).
  return { ...workflow, actions: applyOverlayToActions(workflow.actions, overlay, ctx) };
}

// ── Resolver wiring (used by the store at the executeWorkflows call site) ─────

/**
 * Resolve the overlay for one workflow given a trigger record (a follow-up) and
 * the live assignment/version state. Returns null when there is no applicable
 * overlay — the engine then runs the workflow unchanged (legacy/default path).
 */
export interface SalesOverlayResolverDeps {
  /** Active assignment per client id (only is_active rows). */
  assignmentsByClient: Map<string, ClientSalesProcessAssignment>;
  /** All process versions by id. */
  versionsById: Map<string, SalesProcessVersion>;
}

/** Read the client id off a follow-up record (lookup field is array-or-scalar). */
export function readClientId(record: AppRecord): string | null {
  const v = record.data.client_id;
  if (Array.isArray(v)) return (v[0] as string) ?? null;
  return typeof v === 'string' ? v : null;
}

/**
 * Build the resolveProcessOverlay callback the engine consumes. Given a workflow
 * + the trigger follow-up, it finds the trigger client's active assignment, then
 * its process version config, then that workflow's overlay, and returns a
 * config-overlaid copy of the workflow (or the same workflow when nothing
 * applies). This is the Option-A "config overlay" approach: one engine, the
 * Studio config only adjusts safe values.
 */
export function buildProcessOverlayResolver(
  deps: SalesOverlayResolverDeps,
): (workflow: Workflow, triggerRecord: AppRecord) => Workflow {
  return (workflow, triggerRecord) => {
    // Only follow-up-triggered workflows participate (the sales lifecycle).
    const clientId = readClientId(triggerRecord);
    if (!clientId) return workflow;
    const assignment = deps.assignmentsByClient.get(clientId);
    if (!assignment || !assignment.sales_process_version_id) return workflow;
    const version = deps.versionsById.get(assignment.sales_process_version_id);
    if (!version) return workflow;
    const overlay = version.config_json?.workflows?.[workflow.id];
    if (overlayIsEmpty(overlay)) return workflow;
    const attemptRaw = triggerRecord.data.followup_number;
    const ctx: SalesOverlayContext = {
      attemptNumber: typeof attemptRaw === 'number' ? attemptRaw : null,
    };
    return applyProcessOverlayToWorkflow(workflow, overlay, ctx);
  };
}

// ── resolveSalesProcessRule — the Option-B helper surface ────────────────────

export interface ResolvedSalesProcessRule {
  /** True when an assignment + version overlay applies to this client+activity. */
  hasOverride: boolean;
  /** The resolved overlay for the bound workflow (if any). */
  overlay?: SalesWorkflowOverlay;
  version?: SalesProcessVersion;
  assignment?: ClientSalesProcessAssignment;
  /** Why this client is on this process/version (for the assignment panel). */
  reason?: string | null;
}

/**
 * Inspect what (if anything) a client's assigned process version changes for a
 * given workflow — used by UIs that want to SHOW the effective config (the
 * Journey Map, the client journey panel) without running the engine. The engine
 * itself uses buildProcessOverlayResolver; this is the read-only twin.
 */
export function resolveSalesProcessRule(
  clientId: string,
  workflowId: string | null | undefined,
  deps: SalesOverlayResolverDeps,
): ResolvedSalesProcessRule {
  const assignment = deps.assignmentsByClient.get(clientId);
  if (!assignment || !assignment.sales_process_version_id) return { hasOverride: false };
  const version = deps.versionsById.get(assignment.sales_process_version_id);
  if (!version) return { hasOverride: false, assignment, reason: assignment.assignment_reason };
  const overlay = workflowId ? version.config_json?.workflows?.[workflowId] : undefined;
  return {
    hasOverride: !overlayIsEmpty(overlay),
    overlay,
    version,
    assignment,
    reason: assignment.assignment_reason,
  };
}
